// 1) Verify the HMAC over the RAW body (not re-serialised JSON), 2) enforce the 300 s replay window,
// 3) compare in constant time, 4) validate the payload shape. Output: { ok, status, ...event }.
const crypto = require('crypto');
const SECRET = $env.CONVEX_TO_N8N_SECRET;
if (!SECRET) throw new Error('CONVEX_TO_N8N_SECRET is not set in the n8n container');
// The signature binds method + path, so a signed body cannot be replayed against another endpoint.
const METHOD = 'POST';
const PATHNAME = '/webhook/lendloop-request';
const TYPES = ['request.created', 'request.approved', 'request.declined', 'request.cancelled', 'loan.returned'];
const reject = (status) => [{ json: { ok: false, status } }];

const item = $input.first();
const headers = item.json.headers || {};
const ts = Number(headers['x-lendloop-timestamp']);
const sig = String(headers['x-lendloop-signature'] || '');
if (!Number.isInteger(ts) || Math.abs(Date.now() / 1000 - ts) > 300 || !sig.startsWith('v1=')) return reject(401);

const rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const expected = 'v1=' + crypto.createHmac('sha256', SECRET)
  .update('v1:' + ts + ':' + METHOD + ':' + PATHNAME + ':' + rawBody).digest('hex');
const a = Buffer.from(sig);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject(401);

// Signature is valid from here on, so a bad payload is a client bug (400), not an attack (401).
let e;
try { e = JSON.parse(rawBody); } catch { return reject(400); }
const s = (v) => typeof v === 'string' && v.length > 0;
if (!s(e.eventId) || !TYPES.includes(e.type) || !s(e.recipient?.email) || !s(e.recipient?.firstName)
  || !s(e.tool?.name) || !s(e.loan?.startDate) || !s(e.loan?.endDate) || !/^[^\s@]+@[^\s@]+$/.test(e.recipient.email)) {
  return reject(400);
}
return [{ json: { ok: true, status: 200, eventId: e.eventId, type: e.type, occurredAt: e.occurredAt,
  recipient: { firstName: e.recipient.firstName, email: e.recipient.email },
  counterpartyFirstName: e.counterpartyFirstName || 'Someone', tool: { name: e.tool.name }, loan: e.loan } }];

// Build the e-mail from the payload fields only. Control characters are stripped from every
// interpolated value so a tool name cannot inject extra header lines.
const c = (v) => String(v ?? '').replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, 120);
const e = $json;
const who = c(e.counterpartyFirstName), tool = c(e.tool.name), dates = c(e.loan.startDate) + ' to ' + c(e.loan.endDate);
const M = {
  'request.created':   [`New borrow request: ${tool}`,        `${who} would like to borrow your ${tool} from ${dates}. Open LendLoop to approve or decline.`],
  'request.approved':  [`Request approved: ${tool}`,          `${who} approved your request to borrow ${tool} from ${dates}.`],
  'request.declined':  [`Request declined: ${tool}`,          `${who} declined your request to borrow ${tool} for ${dates}.`],
  'request.cancelled': [`Request cancelled: ${tool}`,         `The request to borrow your ${tool} for ${dates} was cancelled.`],
  'loan.returned':     [`Returned: ${tool}`,                  `${who} marked ${tool} (${dates}) as returned. Thanks for using LendLoop.`],
};
const [subject, body] = M[e.type];
return { json: { to: e.recipient.email, subject, text: `Hi ${c(e.recipient.firstName)},\n\n${body}\n\nLendLoop` } };

// A failed e-mail is still reported (as "failed"), never dropped. The error text is kept short and free of addresses.
const e = $('Skip already processed events').item.json;
const msg = String($json.error?.message || $json.error || 'email send failed').replace(/[^\s@<>]+@[^\s@<>]+/g, '[email]').replace(/\s+/g, ' ').slice(0, 200);
return { json: { eventId: e.eventId, status: 'failed', error: msg } };

// Canonical string: "v1:" + ts + ":" + METHOD + ":" + pathname + ":" + rawBody
const crypto = require('crypto');
function sign(secret, method, pathname, rawBody) {
  const ts = String(Math.floor(Date.now() / 1000));
  const hex = crypto.createHmac('sha256', secret).update('v1:' + ts + ':' + method + ':' + pathname + ':' + rawBody).digest('hex');
  return { 'X-LendLoop-Timestamp': ts, 'X-LendLoop-Signature': 'v1=' + hex };
}
const SECRET = $env.N8N_TO_CONVEX_SECRET;
if (!SECRET) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n container');
const BASE = String($env.CONVEX_SITE_URL || '').replace(/\/+$/, '');
if (!BASE) throw new Error('CONVEX_SITE_URL is not set in the n8n container');
const PATHNAME = '/n8n/notifications';
return $input.all().map((it) => {
  const body = JSON.stringify(it.json); // exact bytes that the HTTP node sends
  return { json: { url: BASE + PATHNAME, body, headers: sign(SECRET, 'POST', PATHNAME, body), status: it.json.status, error: it.json.error } };
});
